={{ (() => {
  const cfg = $json;
  const script = `
const fs = require('fs');
const path = require('path');

const cfg = ${JSON.stringify($json)};
const AI_KEYWORDS = [
  'ai', 'artificial intelligence', 'llm', 'agent', 'agents', 'openai', 'anthropic',
  'gemini', 'claude', 'gpt', 'copilot', 'model', 'inference', 'multimodal', 'reasoning'
];
const DEFAULT_SOURCES = ['hn', 'engadget', 'fast-company', 'the-verge'];

function slugify(value) {
  return String(value || '').trim().toLowerCase().replace(/[^a-z0-9._-]+/g, '-').replace(/-+/g, '-').replace(/^-|-$/g, '') || 'default';
}

function ensureDir(dir) {
  fs.mkdirSync(dir, { recursive: true });
}

function decodeHtml(value) {
  return String(value || '')
    .replace(/<!\\[CDATA\\[(.*?)\\]\\]>/gs, '$1')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&#8217;/g, "'")
    .replace(/&#8211;/g, '-')
    .replace(/&#8220;/g, '"')
    .replace(/&#8221;/g, '"')
    .replace(/&#8230;/g, '...')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\\s+/g, ' ')
    .trim();
}

function containsAi(text) {
  const normalized = String(text || '').toLowerCase();
  return AI_KEYWORDS.some((keyword) => normalized.includes(keyword));
}

async function fetchText(url) {
  const res = await fetch(url, {
    headers: {
      'user-agent': 'Mozilla/5.0 (compatible; n8n-hotspot-collector/1.0)',
      'accept': 'application/json, text/xml, application/xml, text/html;q=0.9, */*;q=0.8'
    }
  });
  if (!res.ok) {
    throw new Error('Fetch failed: ' + url + ' (' + res.status + ')');
  }
  return await res.text();
}

async function fetchJson(url) {
  const text = await fetchText(url);
  return JSON.parse(text);
}

function parseRss(xml) {
  const items = [];
  const itemRegex = /<item\\b[\\s\\S]*?<\\/item>/gi;
  let match;
  while ((match = itemRegex.exec(xml)) !== null) {
    items.push(match[0]);
  }
  return items;
}

function tagValue(block, tag) {
  const regex = new RegExp('<' + tag + '(?:\\s[^>]*)?>([\\s\\S]*?)<\\/' + tag + '>', 'i');
  const match = block.match(regex);
  return match ? decodeHtml(match[1]) : '';
}

function imageFromItem(block) {
  const patterns = [
    /<media:content[^>]*url=["']([^"']+)["']/i,
    /<enclosure[^>]*url=["']([^"']+)["']/i,
    /<img[^>]*src=["']([^"']+)["']/i
  ];
  for (const pattern of patterns) {
    const match = block.match(pattern);
    if (match) return match[1];
  }
  return '';
}

async function collectHn(limit) {
  const data = await fetchJson('https://hn.algolia.com/api/v1/search?tags=front_page');
  const hits = Array.isArray(data.hits) ? data.hits : [];
  return hits
    .filter((hit) => containsAi(hit.title || '') || containsAi(hit.url || '') || containsAi(hit.story_text || ''))
    .slice(0, limit)
    .map((hit) => ({
      source: 'hn',
      title: decodeHtml(hit.title || ''),
      url: hit.url || ('https://news.ycombinator.com/item?id=' + hit.objectID),
      summary: decodeHtml(hit.story_text || hit.comment_text || ''),
      image: ''
    }));
}

async function collectRss(source, url, limit, filterFn) {
  const xml = await fetchText(url);
  const items = parseRss(xml);
  const out = [];
  for (const item of items) {
    const title = tagValue(item, 'title');
    const link = tagValue(item, 'link');
    const description = tagValue(item, 'description') || tagValue(item, 'content:encoded');
    const image = imageFromItem(item);
    if (!filterFn({ title, link, description, image })) continue;
    out.push({ source, title, url: link, summary: description, image });
    if (out.length >= limit) break;
  }
  return out;
}

function normalizeTitle(title) {
  return String(title || '').toLowerCase().replace(/[^a-z0-9\\u4e00-\\u9fa5]+/g, ' ').replace(/\\s+/g, ' ').trim();
}

function dedupe(items) {
  const seen = new Set();
  const out = [];
  for (const item of items) {
    const key = normalizeTitle(item.title);
    if (!key || seen.has(key)) continue;
    seen.add(key);
    out.push(item);
  }
  return out;
}

async function downloadImage(url, targetPath) {
  if (!url) return false;
  try {
    const res = await fetch(url, { headers: { 'user-agent': 'Mozilla/5.0 (compatible; n8n-hotspot-collector/1.0)' } });
    if (!res.ok) return false;
    const buffer = Buffer.from(await res.arrayBuffer());
    fs.writeFileSync(targetPath, buffer);
    return true;
  } catch {
    return false;
  }
}

function fallbackDigest(items, dateStr) {
  const title = (cfg.titlePrefix || '今日 AI 热点速读') + '（' + dateStr + '）';
  const intro = '今天我们从多个公开科技来源里筛选出最值得关注的 AI 动态，整理成一份可快速审阅的热点速读。';
  const lines = ['# ' + title, '', intro, ''];
  if (items.length) {
    lines.push('## 今日概览', '');
    for (const item of items) {
      lines.push('- ' + item.title);
    }
    lines.push('');
  }
  items.forEach((item, index) => {
    lines.push('## ' + (index + 1) + '. ' + item.title, '');
    if (item.localImage) {
      lines.push('![' + item.title + '](' + item.localImage + ')', '');
    }
    lines.push((item.summary || '暂无摘要，可进入原文查看详情。').trim(), '');
    lines.push('原文：' + item.url, '');
  });
  return lines.join('\n').trim() + '\n';
}

async function rewriteWithGemini(items, dateStr) {
  const apiKey = process.env.GEMINI_API_KEY || process.env.GOOGLE_API_KEY;
  if (!apiKey || cfg.rewriteMode === 'off') return null;
  const model = cfg.rewriteModel || 'gemini-3-pro-preview';
  const prompt = [
    '你是中文科技媒体编辑。请基于下面的热点条目，写一篇可读性较强的中文 Markdown 速读稿。',
    '要求：',
    '1. 保留一级标题，格式为：# ' + (cfg.titlePrefix || '今日 AI 热点速读') + '（' + dateStr + '）',
    '2. 先写 1 段导语，再写“今日概览”小节。',
    '3. 每条新闻用二级标题，写成自然中文，不要只堆字段。',
    '4. 每条保留原文链接一行：原文：<url>',
    '5. 不要编造事实，信息不足时保守表述。',
    '6. 输出纯 Markdown，不要代码块。',
    '',
    JSON.stringify(items.map(({ source, title, url, summary, localImage }) => ({ source, title, url, summary, localImage })), null, 2)
  ].join('\n');

  const response = await fetch('https://generativelanguage.googleapis.com/v1beta/models/' + model + ':generateContent?key=' + apiKey, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.6 }
    })
  });

  if (!response.ok) return null;
  const data = await response.json();
  const text = data?.candidates?.[0]?.content?.parts?.map((part) => part.text || '').join('').trim();
  return text || null;
}

async function main() {
  const dateStr = cfg.date || new Date().toISOString().slice(0, 10);
  const outputRoot = cfg.outputRoot || '/tmp/ai-hotspot-digests';
  const packageDir = path.join(outputRoot, dateStr, slugify(cfg.rewriteModel || cfg.rewriteProvider || 'portable'));
  const imagesDir = path.join(packageDir, 'images');
  ensureDir(imagesDir);

  const sourceList = String(cfg.sources || DEFAULT_SOURCES.join(',')).split(',').map((s) => s.trim()).filter(Boolean);
  const limit = Number(cfg.limitPerSource || 3);
  let items = [];

  if (sourceList.includes('hn')) {
    items = items.concat(await collectHn(limit));
  }
  if (sourceList.includes('engadget')) {
    items = items.concat(await collectRss('engadget', 'https://www.engadget.com/rss.xml', limit, (item) => item.link.includes('/ai/') || containsAi(item.title) || containsAi(item.description)));
  }
  if (sourceList.includes('fast-company')) {
    items = items.concat(await collectRss('fast-company', 'https://www.fastcompany.com/section/artificial-intelligence/rss', limit, (item) => containsAi(item.title) || containsAi(item.description)));
  }
  if (sourceList.includes('the-verge')) {
    items = items.concat(await collectRss('the-verge', 'https://www.theverge.com/rss/index.xml', limit, (item) => item.link.includes('/ai') || containsAi(item.title) || containsAi(item.description)));
  }

  items = dedupe(items).slice(0, 6);

  const downloadedImages = [];
  if (cfg.downloadImages !== false) {
    for (let index = 0; index < items.length; index++) {
      const item = items[index];
      if (!item.image) continue;
      const ext = path.extname(new URL(item.image).pathname) || '.jpg';
      const localName = String(index + 1).padStart(2, '0') + ext;
      const localPath = path.join(imagesDir, localName);
      const ok = await downloadImage(item.image, localPath);
      if (ok) {
        item.localImage = 'images/' + localName;
        downloadedImages.push(localPath);
      }
    }
  }

  if (downloadedImages.length) {
    const coverTarget = path.join(imagesDir, 'cover' + path.extname(downloadedImages[0]));
    if (!fs.existsSync(coverTarget)) {
      fs.copyFileSync(downloadedImages[0], coverTarget);
    }
  }

  const markdown = (cfg.rewriteProvider === 'gemini' || cfg.rewriteProvider === 'auto') ? (await rewriteWithGemini(items, dateStr)) || fallbackDigest(items, dateStr) : fallbackDigest(items, dateStr);
  const digestPath = path.join(packageDir, '00-今日AI热点速读.md');
  const manifestPath = path.join(packageDir, 'manifest.json');
  const summaryPath = path.join(packageDir, 'summary.json');
  const sourceItemsPath = path.join(packageDir, 'source-items.json');

  fs.writeFileSync(digestPath, markdown, 'utf8');
  fs.writeFileSync(sourceItemsPath, JSON.stringify(items, null, 2), 'utf8');
  fs.writeFileSync(manifestPath, JSON.stringify({
    date: dateStr,
    packageDir,
    digestPath,
    sources: sourceList,
    itemCount: items.length,
    items: items.map(({ source, title, url, localImage }) => ({ source, title, url, localImage: localImage || '' }))
  }, null, 2), 'utf8');
  fs.writeFileSync(summaryPath, JSON.stringify({
    rewriteProvider: cfg.rewriteProvider,
    rewriteModel: cfg.rewriteModel,
    outputRoot,
    packageDir,
    generatedAt: new Date().toISOString()
  }, null, 2), 'utf8');

  process.stdout.write(JSON.stringify({
    ok: true,
    stage: 'prepared',
    packageDir,
    digestPath,
    manifestPath,
    summaryPath,
    sourceItemsPath,
    imageCount: downloadedImages.length,
    itemCount: items.length
  }, null, 2));
}

main().catch((error) => {
  process.stdout.write(JSON.stringify({ ok: false, error: String(error && error.stack || error) }, null, 2));
  process.exit(1);
});
`;
  return 'node -e ' + JSON.stringify(script);
})() }}

