const raw = ($json.stdout || '').trim();
if (!raw) {
  throw new Error('Collector command returned empty stdout');
}
const data = JSON.parse(raw);
if (!data.ok) {
  throw new Error(`Portable collector failed: ${data.error || raw}`);
}
return [{ json: data }];
